INSERT INTO dbo.[Vessel] ([ID], [VesselCode], [VesselName], [VesselType], [LengthM], [BeamM], [SpeedKts], [HomeBerthLocationID], [MMSI], [MapColor], [MapStroke], [ContractorID], [ActiveFrom], [RetiredOn], [ReplacedVesselID], [SpecsProvisional], [Notes], [IsActive], [IsDeleted], [IMO], [CallSign], [Flag]) VALUES (6, N'JUNO', N'Allianz Juno', N'SV — Fast Crew Boat', 48.00, 11.00, 14.00, 7, N'636025030', N'#f5b400', N'#7a5500', NULL, NULL, '2026-05-20', NULL, 0, N'Replaced by Charlie 3, whose first report is 20 May 2026; Juno''s last is 16 May. Without retired_on the app would carry Juno''s final position forward for ever and draw it alongside Charlie 3 at the same berth, showing two vessels where there is one.', 1, 0, NULL, NULL, NULL);
INSERT INTO dbo.[Vessel] ([ID], [VesselCode], [VesselName], [VesselType], [LengthM], [BeamM], [SpeedKts], [HomeBerthLocationID], [MMSI], [MapColor], [MapStroke], [ContractorID], [ActiveFrom], [RetiredOn], [ReplacedVesselID], [SpecsProvisional], [Notes], [IsActive], [IsDeleted], [IMO], [CallSign], [Flag]) VALUES (7, N'CH3', N'Charlie 3', N'SV — Fast Crew Boat', 42.00, 7.00, 14.00, 7, N'341930000', N'#8b5cf6', N'#4c2889', NULL, '2026-05-20', NULL, NULL, 1, N'Charlie 3 took over Allianz Juno''s role and berth on 20 May 2026, the date of its first report; Juno is retired on that date (see JUNO.retired_on) so only one of the two is ever on the map. Berth B4 is confirmed by its own logs (''VSL STBY ALS TO B# 4 IN SHUAIBA PORT''). IDENTITY CONFIRMED 2026-07-29 against public trackers: MyShipTracking lists MMSI 341930000 as ''High speed craft'', 42 x 7 m, call sign V4DX4, flag St Kitts & Nevis, with 144 arrivals at Shuaiba in the past year on a Shuaiba<->Dubai pattern, and its last recorded position (29.04054, 48.15859) is 12 m from our own Berth 4 coordinates — i.e. the same mooring. That settles the earlier worry that this was the wrong hull: VesselFinder''s ''Offshore Tug/Supply'' label is just a coarser classification of the same ship. Length and beam above are now those real 42 x 7 m figures, replacing Juno''s 48 x 11 m stand-in; speed_kts 14 is still Juno''s number and remains unverified, which is why specs_provisional stays true. Its fuel tank is 55 m3 against Juno''s 147 m3, consistent with the smaller hull. The .env AIS_MMSI_CH3 entry is what the pollers actually read; these fields are documentation.', 1, 0, N'9889928', N'V4DX4', N'St Kitts & Nevis');
